import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/getisord/getisord_crime_second_half_2019.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace the missing value in the crime_rate_value column with the citywide average
citywide_avg = crime_data['crime_rate_value'].mean()
crime_data['crime_rate_value'] = crime_data['crime_rate_value'].fillna(citywide_avg)

# Identify neighbors for each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Combine boroughs with neighbors
combined_values = {}
for borough, neighbor_list in neighbors.items():
    combined_values[borough] = np.mean([crime_data.loc[crime_data['borough'] == b, 'crime_rate_value'].values[0] for b in neighbor_list + [borough]])

# Calculate citywide average
citywide_avg_combined = np.mean(list(combined_values.values()))

# Apply Getis-Ord Gi* method
z_scores = {}
for borough, value in combined_values.items():
    n = len(neighbors[borough]) + 1
    z_scores[borough] = (value - citywide_avg_combined) / (np.std(list(combined_values.values())) * np.sqrt(n / (n - 1)))

# Identify hot and cold spots
hot_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96}
cold_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96 and borough not in hot_spots}

# Report results
data_points_used = len(combined_values)
results = []
for borough, z in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z})")
for borough, z in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z})")
print(f"data_points_used = {data_points_used}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
